const fs = require('fs');
const path = require('path');

// 用 String.raw 或正斜杠，避免 Windows 路径转义
const targetDir = String.raw`D:\finetool\DICOM\YOFO-CBCT-Dubhe(Pirox-D)\吴佳DICOM\吴佳`;

// 你的 form-data 文件字段名
const paramName = 'content';

try {
  if (!fs.existsSync(targetDir)) {
    throw new Error(`目录不存在: ${targetDir}`);
  }

  const filePaths = fs.readdirSync(targetDir)
    .filter(name => name.toLowerCase().endsWith('.dcm'))
    .map(name => path.join(targetDir, name))
    .filter(fullPath => fs.statSync(fullPath).isFile());

  if (filePaths.length === 0) {
    throw new Error(`目录下没有找到 .dcm 文件: ${targetDir}`);
  }

  const formData = pm.request.body.formdata || pm.request.body.formData;

  if (!formData) {
    throw new Error('当前请求 Body 不是 form-data，请先把 Body 类型改为 form-data');
  }

  // 删除原来的 content，包括 content = ["{{file}}"] 这一项
  formData.remove(paramName);

  // 多文件上传：重复添加同名 content 字段
  filePaths.forEach(filePath => {
    formData.add({
      key: paramName,
      type: 'file',
      src: filePath
    });

    console.log(`已添加: ${filePath}`);
  });

  console.log(`成功添加 ${filePaths.length} 个 DCM 文件到 form-data 字段 ${paramName}`);
} catch (err) {
  console.error('前置脚本执行失败:', err.message || err);
}

